import { PlaneGeometry, MeshBasicNodeMaterial, Mesh } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { scenePlacement, interactions, dataBindings } = config;
  const pos = scenePlacement.position;
  const rot = scenePlacement.rotation;
  const scale = scenePlacement.scale;

  // Load texture (cached by ctx)
  const texture = ctx.textureLoader.load('/prism-assets/chrome/ceramic-grain.map.png');

  // Geometry dimensions derived from source rect aspect ratio (512×320)
  const aspect = 512 / 320;
  const geo = new PlaneGeometry(aspect, 1.0);

  // Basic material – lighting not requested
  const mat = new MeshBasicNodeMaterial({ map: texture, transparent: true });

  const mesh = new Mesh(geo, mat);
  mesh.position.set(pos.x, pos.y, pos.z);
  mesh.rotation.set(rot.x, rot.y, rot.z);
  mesh.scale.set(scale.x, scale.y, scale.z);

  // ── Hover interactions ─────────────────────────────────
  const initialY = pos.y;
  let hoverTween = null;

  const onHover = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(mesh.position, {
      y: initialY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  const onUnhover = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(mesh.position, {
      y: initialY,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  // ── Click interaction ──────────────────────────────────
  const onClick = () => {
    // Press-down effect
    gsap.to(mesh.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)',
      yoyo: true,
      repeat: 1,
    });
    // Emit navigation event
    mesh.dispatchEvent({ type: 'navigate', detail: 'hub-collection.select' });
  };

  // ── Attach event handlers ──────────────────────────────
  mesh.userData.handlers = {
    hover: onHover,
    unhover: onUnhover,
    click: onClick,
  };

  // Store data bindings for parent
  if (dataBindings) {
    mesh.userData.dataBindings = dataBindings;
  }

  // ── Resource cleanup ───────────────────────────────────
  mesh.userData.cleanup = () => {
    if (hoverTween) hoverTween.kill();
    geo.dispose();
    mat.dispose();
    if (texture) texture.dispose();
  };

  return mesh;
}
